\section{Proof of Lemma \ref{lem:1}}\label{sec:app1}
We first compute the gradient of $\mathsf{EE}$ by applying the chain rule, which gives
\begin{align}
 \nabla_{\mF} \mathsf{EE} = \frac{\nabla_{\mF} \mathsf{SE} \cdot P_{\mathsf{tot}} - \mathsf{SE} \cdot \nabla_{\mF} P_{\mathsf{tot}}}{(P_{\mathsf{tot}})^2}
 \label{eq:chainf}
 \nabla_{\bPhi} \mathsf{EE} = \frac{\nabla_{\bPhi} \mathsf{SE} \cdot P_{\mathsf{tot}} - \mathsf{SE} \cdot \nabla_{\bPhi} P_{\mathsf{tot}}}{(P_{\mathsf{tot}})^2}
 \label{eq:chaingamma}
\end{align}
To derive the gradient of $\mathsf{SE}$, we first obtain the gradient of $\mathsf{SE}_k$ and then sum the resulting per-user gradients over all users. Based on \eqref{eq:spectral}, $\mathsf{SE}_k$ can be reformulated as
\begin{flalign}
 \mathsf{SE}_k &=  \log_2 \left( 1 + \gamma_k \right)  &&\nonumber &=\log_2 \!\left( \frac{ \sum_{i=1}^{K}\abs{\vhrkH \bPhi \mHt \vfi }^2+ \hat{\sigma}_k^2}{\sum_{i \neq k}^{K} \abs{ \vhrkH \bPhi \mHt \vfi }^2 + \hat{\sigma}_k^2} \right) &&\nonumber&=\! \log_2\!\! \left(\! \frac{\tr{\mF \mFh \mHt^{\mathsf{H}}\bPhi^{\mathsf{H}} \vhrk\vhrkH\bPhi\mHt}\!+ \!\hat{\sigma}_k^2}{\tr{\mF_{\bar{k}}\mF_{\bar{k}}^{\mathsf{H}}\mHt^{\mathsf{H}}\bPhi^{\mathsf{H}} \vhrk\vhrkH\bPhi\mHt} \!+\! \hat{\sigma}_k^2} \right) &&\nonumber&= \log_2 \!\left( \frac{ \tr{\mF \mFh\bar{\mH}_k}+ \hat{\sigma}_k^2}{\tr{\mF_{\bar{k}}\mF_{\bar{k}}^{\mathsf{H}}\bar{\mH}_k} + \hat{\sigma}_k^2} \right) 
 \label{eq:sef}&&
 &=\! \log_2\! \left(\! \frac{ \tr{\bPhi^{\mathsf{H}} \vhrk\vhrkH\bPhi\mHt\mF \mFh\mHt^{\mathsf{H}}}\!+\! \hat{\sigma}_k^2}{\tr{\bPhi^{\mathsf{H}} \vhrk\vhrkH\bPhi\mHt\mF_{\bar{k}}\mF _{\bar{k}}^{\mathsf{H}}\mHt^{\mathsf{H}}}\! +\! \hat{\sigma}_k^2} \right) &&
 \nonumber&=\! \log_2\! \left(\! \frac{ \!\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi\tilde{\mH}}\!+ \!\sigma_k^2\! +\! \sigma_{\mathsf{R}}^2\! \tr{\bPhi^{\mathsf{H}} \mT_k \bPhi}\!}{\!\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi\tilde{\mH}_k}\! + \!\sigma_k^2 \!+ \!\sigma_{\mathsf{R}}^2\! \tr{\bPhi^{\mathsf{H}} \mT_k \bPhi}\!} \!\right)&&
 \nonumber&= \log_2 \!\left(\! \frac{ \tr{\bPhi^{\mathsf{H}} \mT_k\bPhi(\tilde{\mH}\! +\! \sigma_{\mathsf{R}}^2\mI)}\!+\! \sigma_k^2 }{\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi(\tilde{\mH}_k + \sigma_{\mathsf{R}}^2\mI)} + \sigma_k^2} \right)&&
 \nonumber&=\log_2 \left( \frac{ \tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG }+ \sigma_k^2 }{\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi\mG_k} + \sigma_k^2} \right),&&
 \label{eq:segamma}
\end{flalign}
where $\bar{\mH}_k$, $\tilde{\mH}$, and $ \tilde{\mH}_k$ are defined in Lemma \ref{lem:1}.
Using \eqref{eq:sef}, the gradient of $\mathsf{SE}_k$ with respect to $\mF$ is obtained as \cite{hjorungnes2011complex}
\begin{align}
 \nabla_{\mF} \mathsf{SE}_k &=  \frac{\partial }{\partial \mF^*}\log_2\left(\tr{\mF \mFh\bar{\mH}_k}+ \hat{\sigma}_k^2 \right) \nonumber&- \frac{\partial }{\partial \mF^*}\log_2\left(\tr{\mF_{\bar{k}}\mF_{\bar{k}}^{\mathsf{H}}\bar{\mH}_k}+ \hat{\sigma}_k^2 \right)\nonumber&= 2\frac{\bar{\mH}_k\mF}{\ln2\left(\tr{\mF \mFh \bar{\mH}_k}+ \hat{\sigma}_k^2\right)}\nonumber&-2\frac{\bar{\mH}_k\mF_{\bar{k}}}{\ln2\left(\tr{\mF_{\bar{k}}\mF_{\bar{k}}^{\mathsf{H}} \bar{\mH}_k}+ \hat{\sigma}_k^2\right)}.
 \label{gradsekf}
\end{align}
Similarly, using \eqref{eq:segamma}, the gradient of $\mathsf{SE}_k$ with respect to $\bPhi$ is given by
\begin{align}
 \nabla_{\bPhi} \mathsf{SE}_k &=  \frac{\partial }{\partial \bPhi^*}\log_2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG}+ \sigma_k^2\right) \nonumber&- \frac{\partial }{\partial \bPhi^*}\log_2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG_k}+ \sigma_k^2\right)\nonumber&=2\frac{\mT_k\bPhi \mG}{\ln2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG }+ \sigma_k^2\right)}\circ \mI_N\nonumber&-2\frac{\mT_k\bPhi \mG_k}{\ln2\left(\tr{\bPhi^{\mathsf{H}} \mT_k\bPhi \mG_k}+ \sigma_k^2\right)}\circ \mI_N.
 \label{gradsekgamma}
\end{align}
Consequently, the gradients of $\mathsf{SE}$ with respect to $\mF$ and $\bPhi$ are given, respectively, by
\begin{align}
 \nabla_{\mF} \mathsf{SE} = \sum_{k=1}^K \nabla_{\mF} \mathsf{SE}_k,
 \label{gradsef}

 \nabla_{\bPhi} \mathsf{SE} = \sum_{k=1}^K \nabla_{\bPhi} \mathsf{SE}_k.
 \label{gradsegamma}
\end{align}
The gradient of $P_{\mathsf{tot}}$, based on \eqref{eq:powertot}, is given by
\begin{align}
 \nabla_{\mF} P_{\mathsf{tot}} &=\frac{1}{\xi}\mF+\frac{1}{\zeta}\mHt^{\mathsf{H}}\bPhi^{\mathsf{H}}\bPhi\mHt\mF,
 \label{eq:ptotgradf}
 \nabla_{\bPhi} P_{\mathsf{tot}} &= \frac{1}{\zeta}\Big(\bPhi (\tilde{\mH} + \sigma_{\mathsf{R}}^2\mI)\Big)\circ \mI_N= \frac{1}{\zeta}\bPhi \mG\circ \mI_N.
 \label{eq:ptotgradgamma}
\end{align}
Finally, substituting \eqref{gradsef} and \eqref{eq:ptotgradf} into \eqref{eq:chainf} yields \eqref{eq:gradf}. Similarly, substituting \eqref{gradsegamma} and \eqref{eq:ptotgradgamma} into \eqref{eq:chaingamma} gives \eqref{eq:gradgamma}, which completes the proof of Lemma \ref{lem:1}.
